import iframeSrcdoc from './iframe_srcdoc.html';
export function teleportStyle(appendTo = 'head') {
    const $div = $('<div>')
        .attr('script_id', getScriptId())
        .append($('head > style', document).clone())
        .appendTo(appendTo);
    return {
        destroy: () => $div.remove(),
    };
}
export function createScriptIdIframe() {
    return $('<iframe>').attr({
        script_id: getScriptId(),
        frameborder: 0,
        srcdoc: iframeSrcdoc,
    });
}
